import fs from 'node:fs';
import path from 'node:path';
import yaml from 'js-yaml';
import { createReactiveBootloaderReference, SkillManifestSchema } from '@reactive-skills/runtime';
import { AxiError } from '../errors.js';
import { renderDetail, renderList, renderHelp, renderOutput } from '../toon.js';
const JS_GUARD_GLOBALS = new Set([
    'Array',
    'Boolean',
    'Date',
    'JSON',
    'Math',
    'Number',
    'Object',
    'RegExp',
    'String',
    'context',
    'event',
    'false',
    'null',
    'payload',
    'true',
    'undefined',
]);
const COMMON_SIGNAL_FIELD_NAMES = new Set([
    'ack_id',
    'approved',
    'category',
    'confidence',
    'error',
    'exit_code',
    'nop_pass',
    'nop_passed',
    'oracle_pass',
    'oracle_passed',
    'status',
    'subcategory',
    'task_name',
]);
function stripGuardStrings(guard) {
    return guard
        .replace(/`(?:\\.|[^`])*`/g, ' ')
        .replace(/"(?:\\.|[^"])*"/g, ' ')
        .replace(/'(?:\\.|[^'])*'/g, ' ');
}
function lintGuardExpression(guard, contextKeys, stateName, signal) {
    const warnings = [];
    const stripped = stripGuardStrings(guard);
    if (/\bNone\b|\bis\s+(?:not\s+)?None\b/.test(stripped)) {
        warnings.push(`State "${stateName}" transition on "${signal}" guard uses Python-style None syntax; use JavaScript null checks such as payload.field != null`);
    }
    const dataFieldNames = new Set([...contextKeys, ...COMMON_SIGNAL_FIELD_NAMES]);
    const bareFields = new Set();
    const identifierPattern = /\b[A-Za-z_$][A-Za-z0-9_$]*\b/g;
    let match;
    while ((match = identifierPattern.exec(stripped)) !== null) {
        const identifier = match[0];
        const previous = stripped[match.index - 1];
        if (JS_GUARD_GLOBALS.has(identifier) || previous === '.') {
            continue;
        }
        if (dataFieldNames.has(identifier)) {
            bareFields.add(identifier);
        }
    }
    if (bareFields.size > 0) {
        warnings.push(`State "${stateName}" transition on "${signal}" guard references bare data field(s) ${Array.from(bareFields).sort().join(', ')}; use payload.*, event.payload.*, or context.* explicitly`);
    }
    if (/\bcontext\.[A-Za-z_$][A-Za-z0-9_$]*/.test(stripped) && /(?:^|\.)(?:INTAKE|READY|SELECT|START|INITIAL)(?:$|\.)/i.test(stateName)) {
        warnings.push(`State "${stateName}" transition on "${signal}" uses context.* in an intake-like state; if the value is supplied by this signal, prefer payload.* so the guard does not depend on stale context`);
    }
    return warnings;
}
/**
 * Discover skill directories to validate based on target argument or workspace conventions
 */
export function discoverSkillDirs(targetArg) {
    if (targetArg) {
        let resolved = path.resolve(process.cwd(), targetArg);
        // If pointing to a skill.yaml file directly
        if (fs.existsSync(resolved) && fs.statSync(resolved).isFile()) {
            if (resolved.endsWith('skill.yaml') || resolved.endsWith('skill.yml')) {
                return [path.dirname(resolved)];
            }
        }
        // If pointing to a directory that directly contains skill.yaml
        if (fs.existsSync(resolved) && fs.statSync(resolved).isDirectory()) {
            if (fs.existsSync(path.join(resolved, 'skill.yaml')) || fs.existsSync(path.join(resolved, 'skill.yml'))) {
                return [resolved];
            }
            // Check if this directory contains subdirectories with skill.yaml
            const subSkills = findSkillsInDir(resolved);
            if (subSkills.length > 0) {
                return subSkills;
            }
        }
        // Check ./skills/<targetArg>
        const relativeToSkills = path.resolve(process.cwd(), 'skills', targetArg);
        if (fs.existsSync(relativeToSkills) && fs.statSync(relativeToSkills).isDirectory()) {
            if (fs.existsSync(path.join(relativeToSkills, 'skill.yaml')) || fs.existsSync(path.join(relativeToSkills, 'skill.yml'))) {
                return [relativeToSkills];
            }
        }
        throw new AxiError(`Skill not found at "${targetArg}"`, 'NOT_FOUND', [
            'Provide a directory containing skill.yaml',
            'Usage: reactive-skills-axi validate [path-to-skill]',
        ]);
    }
    // Omitted target: check current working directory first
    if (fs.existsSync(path.join(process.cwd(), 'skill.yaml')) || fs.existsSync(path.join(process.cwd(), 'skill.yml'))) {
        return [process.cwd()];
    }
    // Check ./skills/
    const skillsDir = path.resolve(process.cwd(), 'skills');
    if (fs.existsSync(skillsDir) && fs.statSync(skillsDir).isDirectory()) {
        const subSkills = findSkillsInDir(skillsDir);
        if (subSkills.length > 0) {
            return subSkills;
        }
    }
    throw new AxiError('No reactive skills found to validate in current directory', 'NOT_FOUND', [
        'Run from a directory containing skill.yaml or a skills/ directory',
        'Or specify target path: reactive-skills-axi validate <path>',
    ]);
